import * as React from "react";

import { cn } from "../lib/utils";
import { Breadcrumb, type BreadcrumbCrumb } from "./breadcrumb";

import styles from "./top-bar.module.css";

export function AppShell({
  className,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"div"> & { ref?: React.Ref<HTMLDivElement> }) {
  return <div ref={ref} data-slot="app-shell" className={cn(styles.shell, className)} {...props} />;
}
AppShell.displayName = "AppShell";

export function AppInset({
  className,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"main"> & { ref?: React.Ref<HTMLElement> }) {
  return (
    <main
      ref={ref}
      data-slot="app-inset"
      data-scroll-fade="y"
      className={cn(styles.inset, className)}
      {...props}
    />
  );
}
AppInset.displayName = "AppInset";

export function PageGutter({
  className,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"div"> & { ref?: React.Ref<HTMLDivElement> }) {
  return (
    <div ref={ref} data-slot="page-gutter" className={cn(styles.gutter, className)} {...props} />
  );
}
PageGutter.displayName = "PageGutter";

export type TopBarProps = Omit<React.ComponentPropsWithoutRef<"header">, "children"> & {
  breadcrumb: readonly BreadcrumbCrumb[];
  actions?: React.ReactNode;
  label?: string;
};

export function TopBar({
  breadcrumb,
  actions,
  label = "Location",
  className,
  ref,
  ...props
}: TopBarProps & { ref?: React.Ref<HTMLElement> }) {
  return (
    <header ref={ref} data-slot="top-bar" className={cn(styles.topBar, className)} {...props}>
      <Breadcrumb
        aria-label={label}
        variant="product"
        items={breadcrumb}
        className={styles.trail}
      />
      {actions && <div className={styles.actions}>{actions}</div>}
    </header>
  );
}
TopBar.displayName = "TopBar";

.shell {
  --v4-sidebar-tools-top: calc(
    var(--v4-space-shell-gap) + var(--v4-size-control-border) +
      (var(--v4-size-shell-bar) - var(--v4-size-control-md)) / 2
  );
  display: flex;
  min-width: 0;
  height: 100%;
  min-height: 0;
  background: var(--v4-sidebar);
}
/* v4-check-ignore scroll-fade -- the edge fade comes from data-scroll-fade on this element */
.inset {
  --v4-page-gutter: max(
    var(--v4-space-16),
    min(var(--v4-space-40), 5cqi),
    calc((100cqi - var(--v4-size-measure-page)) / 2)
  );
  container-type: inline-size;
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  overflow: auto;
  background: var(--v4-inset);
  color: var(--v4-ink);
}
.shell > .inset {
  margin: var(--v4-space-shell-gap) var(--v4-space-shell-gap) var(--v4-space-shell-gap) 0;
  border: var(--v4-size-control-border) solid var(--v4-line);
  border-radius: calc(var(--v4-radius-panel) * var(--corners));
}
.shell > [data-slot="sidebar"] {
  border-inline-end-color: transparent;
}
.shell > .inset:first-child {
  margin-inline-start: var(--v4-space-shell-gap);
}

.gutter {
  padding: var(--v4-space-40) var(--v4-page-gutter, var(--v4-space-40));
}
.topBar {
  position: sticky;
  top: 0;
  z-index: 1;
  display: flex;
  flex: none;
  align-items: center;
  gap: var(--v4-space-16);
  min-width: 0;
  height: var(--v4-size-shell-bar);
  padding-inline: var(--v4-page-gutter, var(--v4-space-40));
  border-bottom: 1px solid var(--v4-line-soft);
  background: var(--v4-inset);
}
.trail {
  flex: 1 1 auto;
  width: auto;
}
.actions {
  display: flex;
  flex: none;
  align-items: center;
  gap: var(--v4-space-8);
}
